return $input.all().map(item => {
  function findJsonString(obj) {
    if (typeof obj === 'string' && obj.includes('{')) return obj;
    if (obj && typeof obj === 'object') {
      for (let key in obj) {
        let found = findJsonString(obj[key]);
        if (found) return found;
      }
    }
    return null;
  }

  let rawAiOutput = findJsonString(item.json) || "";
  rawAiOutput = rawAiOutput.replace(/```json/g, "").replace(/```/g, "").trim();

  let d;
  try {
    d = JSON.parse(rawAiOutput);
  } catch (e) {
    d = { 
      intent: "other", urgency: "normal", risk_level: "medium", 
      auto_action_allowed: false, recommended_action: "Manual review required due to parsing failure"
    };
  }

  const pick = (v, allowed, fallback) => allowed.includes(v) ? v : fallback;

  // Fix: Force string "true" to become mathematical true
  const isAutoAllowed = (d.auto_action_allowed === true || d.auto_action_allowed === "true");

  const out = {
    intent: pick(d.intent, ["support","billing","technical","sales","feedback","other"], "other"),
    urgency: pick(d.urgency, ["urgent","high","normal","low"], "normal"),
    risk_level: pick(d.risk_level, ["high","medium","low"], "medium"),
    auto_action_allowed: isAutoAllowed,
    recommended_action: (d.recommended_action || "Escalate for manual review").toString(),
    escalation_reason: d.escalation_reason ?? null,
    response_draft: (d.response_draft || "Thanks, we received your request and will follow up shortly.").toString(),
    confidence: typeof d.confidence === "number" ? d.confidence : 0.5
  };

  // Safety override
  if (out.urgency === "urgent" || out.risk_level === "high") {
    out.auto_action_allowed = false;
    if (!out.escalation_reason) out.escalation_reason = "Urgent or high-risk case";
  }

  return { json: out };
});
